"use client";

import { motion } from "framer-motion";
import { Globe, Database, Cpu, Zap, Layout, ShieldCheck, RefreshCw } from "lucide-react";

export default function ExpertisePage() {
  const expertise = [
    { title: "Frontend", items: ["React", "Next.js", "Tailwind CSS", "Framer Motion"], icon: Globe },
    { title: "Backend", items: ["Node.js", "Go", "PostgreSQL", "Redis"], icon: Database },
    { title: "Infrastructure", items: ["AWS", "Kubernetes", "Docker", "CI/CD"], icon: Zap },
    { title: "AI & ML", items: ["OpenAI", "PyTorch", "LLM Integration", "Computer Vision"], icon: Cpu },
  ];

  return (
    <div className="min-h-screen bg-background pt-32 px-8 md:px-16">
      <div className="max-w-7xl mx-auto">
        <motion.h1 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-5xl md:text-7xl font-black text-white mb-8 font-outfit"
        >
          Our <span className="text-primary italic">Expertise.</span>
        </motion.h1>
        <p className="text-xl text-white/50 max-w-3xl mb-24 font-medium leading-relaxed">
          We combine deep technical knowledge with product-thinking to build 
          architectures that don't just work today, but scale for the next decade.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {expertise.map((exp, idx) => (
            <motion.div
              key={exp.title}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.1 }}
              className="glass p-8 rounded-[2rem] border-white/5 hover:border-primary/20 transition-all group"
            >
              <div className="w-14 h-14 bg-white/5 rounded-2xl flex items-center justify-center mb-8 group-hover:bg-primary/20 group-hover:scale-110 transition-all duration-300">
                <exp.icon className="w-8 h-8 text-white group-hover:text-primary transition-colors" />
              </div>
              <h3 className="text-2xl font-bold text-white mb-6 font-outfit">{exp.title}</h3>
              <ul className="space-y-4">
                {exp.items.map((item) => (
                  <li key={item} id={item.toLowerCase().replace(" ", "-")} className="text-white/40 flex items-center gap-2 font-medium">
                    <div className="w-1.5 h-1.5 bg-primary rounded-full" />
                    {item}
                  </li>
                ))}
              </ul>
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
}
